package org.cryptomator.jose.hpke;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import java.util.Base64;

class XwingKeyPairGeneratorSpiTest {

	@Test
	public void testGenerateKey() {
		// test vectors from https://datatracker.ietf.org/doc/html/draft-connolly-cfrg-xwing-kem-07#appendix-C
		var seed = Base64.getDecoder().decode("f5wrpOiPgn1hYEVQdgWFPtc7gJP277yI6xpurPpm7yY=");

		var keyPair = XwingKeyPairGeneratorSpi.generateKeyPairDerand(seed);

		var expectedPk = Base64.getDecoder().decode("");
		Assertions.assertArrayEquals(expectedPk, keyPair.getPublic().getEncoded());

		var pk = (XwingPublicKey) keyPair.getPublic();
		Assertions.assertDoesNotThrow(pk::getX25519PublicKey);
		Assertions.assertDoesNotThrow(pk::getMLKemPublicKey);
	}

}